#include <iostream>
#include <vector>
#include <string>
#include <unordered_set>
#include <sstream>
#include <map>
using namespace std;

class AffineCipher {
public:
    string decode(string, vector<int>);
    vector<int> make_alpha(void);
private:
    int gcd(int, int);
    bool decide_variable(int, int, const string&);
    bool check_code(const string&);
};

int AffineCipher::gcd(int a, int b) {
    while (b) {
        swap(a, b);
        b %= a;
    }
    return a;
}

bool AffineCipher::decide_variable(int a, int b, const string& str) {
    unordered_set<char> code, source;
    for (char ch : str) {
        if (isalpha(ch)) {
            source.insert(ch);
        }
    }
    for (char c : source) {
        char transformed = (a * (c - 'a') + b) % 26 + 'a';
        if (!code.insert(transformed).second) {
            return false;
        }
    }
    return true;
}

bool AffineCipher::check_code(const string& str) {
    const vector<string> keywords = {"this", "that"};
    for (const string& keyword : keywords) {
        if (str.find(keyword) != string::npos) {
            return true;
        }
    }
    return false;
}

string AffineCipher::decode(string str, vector<int> alpha) {
    multimap<int, int> table;
    for (int a : alpha) {
        for (int b = 0; b < 26; ++b) {
            if (decide_variable(a, b, str)) {
                table.emplace(a, b);
            }
        }
    }

    for (const auto& [a, b] : table) {
        string res;
        res.reserve(str.size()); // Optimize by reserving space
        for (char ch : str) {
            if (isalpha(ch)) {
                res += (a * (ch - 'a') + b) % 26 + 'a'; // No change here
            } else {
                res += ch; // Append non-alpha characters
            }
        }
        if (check_code(res)) {
            return res;
        }
    }
    return "";
}

vector<int> AffineCipher::make_alpha(void) {
    vector<int> alpha;
    for (int i = 1; i < 26; ++i) {
        if (gcd(i, 26) == 1) {
            alpha.push_back(i);
        }
    }
    return alpha;
}

int main() {
    AffineCipher AC;
    string str;
    int n;
    getline(cin, str);
    stringstream ssn(str);
    ssn >> n;
    vector<int> alpha = AC.make_alpha();
    for (int i = 0; i < n; ++i) {
        getline(cin, str);
        cout << AC.decode(str, alpha) << endl;
    }
    return 0;
}

